            dnsDiagnostics: {
                /** @example 5 */
                lookupTimeoutSeconds: number;
                /**
                 * @description Runs each caller may start per minute.
                 * @example 10
                 */
                runsPerMinute: number;
                /** @example 30 */
                runTimeoutSeconds: number;
                /**
                 * @description Whether the caller's runs include the server-wide checks (host addresses, reverse names,
                 *     TLSA). `true` for administrators, `false` for domain administrators.
                 */
                serverChecks: boolean;
            };
            /** @example 1000 */
            maxPageSize: number;
            mtaSts: {
                /** @description Active state of a policy created without one (`false`, as in legacy). */
                defaultActive: boolean;
                /** @example 31557600 */
                maxAgeMax: number;
                /** @example 1 */
                maxAgeMin: number;
                /**
                 * @example [
                 *       "enforce",
                 *       "testing",
                 *       "none"
                 *     ]
                 */
                modes: components["schemas"]["MtaStsMode"][];
                /**
                 * @description Maximum length of the MX hosts joined by commas, as mailcow stores them.
                 * @example 255
                 */
                mxMaxLength: number;
                /** @constant */
                version: "STSv1";
            };
